<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban Board</title>
<style>
  :root{
    --bg:#0f1420;
    --panel:#171d2b;
    --panel-2:#1d2434;
    --card:#232b3d;
    --card-hi:#2b3550;
    --text:#e8ecf4;
    --muted:#93a0b8;
    --accent:#5b8cff;
    --accent-2:#3ecf8e;
    --danger:#ff6b6b;
    --radius:14px;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    padding:28px 22px 60px;
    background:
      radial-gradient(1100px 500px at 12% -8%, #1c2740 0%, transparent 60%),
      radial-gradient(900px 500px at 90% 0%, #1a2c3a 0%, transparent 55%),
      var(--bg);
    color:var(--text);
    font:15px/1.45 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing:antialiased;
  }
  header.top{
    max-width:1100px;margin:0 auto 22px;
    display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:space-between;
  }
  h1{
    margin:0;font-size:22px;letter-spacing:.2px;font-weight:650;
    display:flex;align-items:center;gap:10px;
  }
  h1 .dot{width:11px;height:11px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px rgba(91,140,255,.18)}
  .composer{display:flex;gap:8px;align-items:center}
  #new-card{
    width:290px;max-width:60vw;
    padding:11px 13px;border-radius:11px;
    border:1px solid #2c3purple;
    border:1px solid #2c3550;
    background:var(--panel-2);color:var(--text);
    outline:none;transition:border-color .15s, box-shadow .15s;
  }
  #new-card::placeholder{color:#7d8aa3}
  #new-card:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(91,140,255,.2)}
  button{
    font:inherit;cursor:pointer;border:none;border-radius:11px;
    color:#0d1220;background:var(--accent);
    padding:11px 16px;font-weight:650;letter-spacing:.2px;
    transition:transform .08s ease, filter .15s ease;
  }
  button:hover{filter:brightness(1.08)}
  button:active{transform:translateY(1px)}
  #clear-board{background:#2b3550;color:var(--muted);font-weight:550}

  .board{
    max-width:1100px;margin:0 auto;
    display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;
    align-items:start;
  }
  @media (max-width:820px){ .board{grid-template-columns:1fr} }

  .column{
    background:linear-gradient(180deg,var(--panel) 0%, #141a27 100%);
    border:1px solid #262f45;
    border-radius:var(--radius);
    padding:14px 13px 16px;
    min-height:220px;
    display:flex;flex-direction:column;
    transition:border-color .15s, background .15s, box-shadow .15s;
  }
  .column.drag-over{
    border-color:var(--accent);
    box-shadow:0 0 0 3px rgba(91,140,255,.16) inset;
    background:linear-gradient(180deg,#1b2338 0%, #161d2c 100%);
  }
  .col-head{
    display:flex;align-items:center;justify-content:space-between;
    gap:10px;padding:2px 4px 12px;
  }
  .col-title{display:flex;align-items:center;gap:9px;font-weight:650;font-size:14px;letter-spacing:.4px;text-transform:uppercase;color:#cfd8ea}
  .pip{width:9px;height:9px;border-radius:3px;background:var(--accent)}
  #col-doing .pip{background:#f5b544}
  #col-done .pip{background:var(--accent-2)}
  .count{
    min-width:26px;text-align:center;
    background:#2a3450;color:#d6e0f5;
    border-radius:999px;padding:3px 9px;
    font-size:12.5px;font-weight:700;
  }
  .cards{
    display:flex;flex-direction:column;gap:10px;
    min-height:90px;flex:1;
    padding:2px;border-radius:10px;
  }
  .card{
    background:var(--card);
    border:1px solid #303b55;
    border-radius:12px;
    padding:12px 12px 12px 14px;
    display:flex;align-items:flex-start;gap:10px;
    box-shadow:0 6px 16px rgba(0,0,0,.22);
    cursor:grab;
    position:relative;
    transition:background .15s, transform .08s, border-color .15s;
    word-break:break-word;
  }
  .card:hover{background:var(--card-hi);border-color:#3d4a6b}
  .card:active{cursor:grabbing}
  .card.dragging{opacity:.45;transform:rotate(-1deg)}
  .card-title{flex:1;min-width:0;font-size:14.5px}
  .card-del{
    background:transparent;color:var(--muted);
    padding:2px 7px;border-radius:8px;font-size:16px;line-height:1;
    font-weight:700;
  }
  .card-del:hover{background:rgba(255,107,107,.14);color:var(--danger);filter:none}
  .empty{
    color:#6f7d97;font-size:13px;text-align:center;
    border:1px dashed #2f3a54;border-radius:10px;padding:16px 8px;
  }
  footer.hint{max-width:1100px;margin:22px auto 0;color:#6f7d97;font-size:12.5px;text-align:center}
</style>
</head>
<body>

<header class="top">
  <h1><span class="dot"></span>Kanban Board</h1>
  <div class="composer">
    <input id="new-card" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New card title">
    <button id="add-card" type="button">Add Card</button>
    <button id="clear-board" type="button">Clear</button>
  </div>
</header>

<main class="board">
  <section class="column" id="col-todo" data-col="todo">
    <div class="col-head">
      <div class="col-title"><span class="pip"></span>To Do</div>
      <span class="count">0</span>
    </div>
    <div class="cards" data-cards="todo"></div>
  </section>

  <section class="column" id="col-doing" data-col="doing">
    <div class="col-head">
      <div class="col-title"><span class="pip"></span>Doing</div>
      <span class="count">0</span>
    </div>
    <div class="cards" data-cards="doing"></div>
  </section>

  <section class="column" id="col-done" data-col="done">
    <div class="col-head">
      <div class="col-title"><span class="pip"></span>Done</div>
      <span class="count">0</span>
    </div>
    <div class="cards" data-cards="done"></div>
  </section>
</main>

<footer class="hint">Drag cards between columns &middot; your board is saved locally</footer>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban.board.v1";
  var COLS = ["todo", "doing", "done"];

  var state = load();
  var draggingId = null;

  /* ---------- storage ---------- */
  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data
        .filter(function (c) { return c && typeof c.title === "string"; })
        .map(function (c) {
          return {
            id: String(c.id || nextId()),
            title: String(c.title),
            col: COLS.indexOf(c.col) >= 0 ? c.col : "todo"
          };
        });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  var seq = 0;
  function nextId() {
    seq += 1;
    return "c" + Date.now().toString(36) + "-" + seq;
  }

  /* ---------- rendering ---------- */
  function render() {
    COLS.forEach(function (col) {
      var container = document.querySelector('[data-cards="' + col + '"]');
      container.innerHTML = "";
      var items = state.filter(function (c) { return c.col === col; });

      items.forEach(function (card) {
        container.appendChild(buildCard(card));
      });

      if (items.length === 0) {
        var empty = document.createElement("div");
        empty.className = "empty";
        empty.textContent = "Drop cards here";
        container.appendChild(empty);
      }

      var countEl = document.querySelector("#col-" + col + " .count");
      countEl.textContent = String(items.length);
    });
  }

  function buildCard(card) {
    var el = document.createElement("div");
    el.className = "card";
    el.setAttribute("draggable", "true");
    el.dataset.id = card.id;

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;

    var del = document.createElement("button");
    del.className = "card-del";
    del.type = "button";
    del.title = "Delete card";
    del.setAttribute("aria-label", "Delete card");
    del.textContent = "\u00d7";
    del.addEventListener("click", function (ev) {
      ev.stopPropagation();
      deleteCard(card.id);
    });
    del.addEventListener("dragstart", function (ev) { ev.preventDefault(); });

    el.appendChild(title);
    el.appendChild(del);

    el.addEventListener("dragstart", function (ev) {
      draggingId = card.id;
      el.classList.add("dragging");
      if (ev.dataTransfer) {
        ev.dataTransfer.effectAllowed = "move";
        try { ev.dataTransfer.setData("text/plain", card.id); } catch (e) {}
      }
    });

    el.addEventListener("dragend", function () {
      draggingId = null;
      el.classList.remove("dragging");
      document.querySelectorAll(".column.drag-over").forEach(function (c) {
        c.classList.remove("drag-over");
      });
    });

    return el;
  }

  /* ---------- mutations ---------- */
  function addCard(rawTitle) {
    var title = String(rawTitle == null ? "" : rawTitle).trim();
    if (!title) return false;
    state.push({ id: nextId(), title: title, col: "todo" });
    save();
    render();
    return true;
  }

  function deleteCard(id) {
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col, beforeId) {
    if (COLS.indexOf(col) < 0) return;
    var card = null;
    for (var i = 0; i < state.length; i++) {
      if (state[i].id === id) { card = state[i]; break; }
    }
    if (!card) return;
    if (beforeId === id) beforeId = null;

    card.col = col;
    var rest = state.filter(function (c) { return c.id !== id; });
    var idx = beforeId ? rest.findIndex(function (c) { return c.id === beforeId; }) : -1;
    if (idx < 0) rest.push(card); else rest.splice(idx, 0, card);
    state = rest;

    save();
    render();
  }

  /* ---------- drag & drop targets ---------- */
  function cardIdBefore(column, clientY) {
    var cards = Array.prototype.slice.call(column.querySelectorAll(".card"));
    for (var i = 0; i < cards.length; i++) {
      if (cards[i].dataset.id === draggingId) continue;
      var box = cards[i].getBoundingClientRect();
      if (clientY < box.top + box.height / 2) return cards[i].dataset.id;
    }
    return null;
  }

  COLS.forEach(function (col) {
    var column = document.getElementById("col-" + col);

    column.addEventListener("dragover", function (ev) {
      ev.preventDefault();
      if (ev.dataTransfer) ev.dataTransfer.dropEffect = "move";
      column.classList.add("drag-over");
    });

    column.addEventListener("dragenter", function (ev) {
      ev.preventDefault();
      column.classList.add("drag-over");
    });

    column.addEventListener("dragleave", function (ev) {
      if (ev.relatedTarget && column.contains(ev.relatedTarget)) return;
      column.classList.remove("drag-over");
    });

    column.addEventListener("drop", function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      column.classList.remove("drag-over");
      var id = "";
      if (ev.dataTransfer) {
        try { id = ev.dataTransfer.getData("text/plain") || ""; } catch (e) { id = ""; }
      }
      if (!id) id = draggingId || "";
      if (!id) return;
      var before = cardIdBefore(column, ev.clientY);
      moveCard(id, col, before);
      draggingId = null;
    });
  });

  /* ---------- controls ---------- */
  var input = document.getElementById("new-card");
  var addBtn = document.getElementById("add-card");
  var clearBtn = document.getElementById("clear-board");

  function submit() {
    if (addCard(input.value)) input.value = "";
    else input.value = "";
    input.focus();
  }

  addBtn.addEventListener("click", submit);
  input.addEventListener("keydown", function (ev) {
    if (ev.key === "Enter") { ev.preventDefault(); submit(); }
  });

  clearBtn.addEventListener("click", function () {
    state = [];
    save();
    render();
  });

  render();
})();
</script>
</body>
</html>
